# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">ESKİCİ HİKÂYESİNİN (REFİK HALİT KARAY) ÇÖZÜMLEMESİ</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Hikâye Unsurları ve Bölümleri (T.O.7.16)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Kişiler: Küçük Hasan (5 yaşında), Anadolu\'dan gelen</text>\n  <text x="40" y="116" font-size="11" fill="#334155">  ihtiyar Eskici (ayakkabı tamircisi), Halası, Arap kadınlar</text>\n  <text x="40" y="138" font-size="11" fill="#334155">• Mekân: Vapur yolculuğu ve Filistin\'de (Hayfa/Akka)</text>\n  <text x="40" y="156" font-size="11" fill="#334155">  Arapça konuşulan uzak bir kasabadaki hala evi</text>\n  <text x="40" y="178" font-size="11" fill="#334155">• Olay: Annesini-babasını kaybeden Hasan\'ın dilini</text>\n  <text x="40" y="196" font-size="11" fill="#334155">  bilmediği diyarda Türkçe konuşan Eskici\'ye sığınması</text>\n  <text x="182" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Tür: Olay Hikâyesi (Serim - Düğüm - Çözüm)</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">Ana Fikir, Ana Duygu ve Anahtar Kavramlar</text>\n  <text x="375" y="98" font-size="11" font-weight="bold" fill="#9d174d">• Ana Duygu:</text>\n  <text x="375" y="118" font-size="11" fill="#334155">  Gurbet acısı, memleket ve ana dili özlemi, yalnızlık.</text>\n  <text x="375" y="144" font-size="11" font-weight="bold" fill="#9d174d">• Ana Fikir (İleti):</text>\n  <text x="375" y="164" font-size="11" fill="#334155">  Ana dili, insanın vatanıyla ve kimliğiyle en güçlü</text>\n  <text x="375" y="182" font-size="11" fill="#334155">  iletişim bağıdır; gurbette ana dilini duymak yuva</text>\n  <text x="375" y="200" font-size="11" fill="#334155">  sıcaklığı verir ("Ağzındaki çiviler..." sahnesi).</text>\n  <text x="517" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#be185d">Tema: İletişim ve Sosyal İlişkiler</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">SÖZCÜK TÜRLERİ: ZARFLAR (BELİRTEÇLER) VE 5 TEMEL TÜRÜ</text>\n  <rect x="20" y="48" width="320" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="180" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">1. Durum, Zaman ve Miktar Zarfları</text>\n  <text x="34" y="100" font-size="11" fill="#334155">• Durum (Niteleme) Zarfı → Fiile "Nasıl?" sorusu:</text>\n  <text x="34" y="118" font-size="10.5" fill="#166534">  "Hasan eskiciyi sessizce ve dikkatle izliyordu."</text>\n  <text x="34" y="142" font-size="11" fill="#334155">• Zaman Zarfı → Fiile "Ne zaman?" sorusu:</text>\n  <text x="34" y="160" font-size="10.5" fill="#166534">  "Bir gün eve ihtiyar bir eskici geldi. (dün, şimdi, akşam)"</text>\n  <text x="34" y="184" font-size="11" fill="#334155">• Miktar (Azlık-Çokluk) Zarfı → "Ne kadar?" sorusu:</text>\n  <text x="34" y="202" font-size="10.5" fill="#166534">  "Çok ağladı, biraz sustu, en güzel yıllar, pek hızlı"</text>\n  <text x="180" y="224" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Miktar zarfı fiili, sıfatı ve başka bir zarfı derecelendirir!</text>\n  <rect x="360" y="48" width="320" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="520" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#a16207">2. Yer-Yön ve Soru Zarfları</text>\n  <text x="374" y="100" font-size="11" fill="#334155">• Yer-Yön Zarfı → Fiile "Nereye?" (Yalın hâlde!):</text>\n  <text x="374" y="118" font-size="10.5" fill="#92400e">  "İçeri, dışarı, aşağı, yukarı, ileri, geri, öte, beri"</text>\n  <text x="374" y="138" font-size="10.5" font-weight="bold" fill="#b91c1c">  Dikkat: Ek alırsa ("içeriye, dışarıda") İSİM olur!</text>\n  <text x="374" y="164" font-size="11" fill="#334155">• Soru Zarfı → Fiili soru yoluyla belirtenler:</text>\n  <text x="374" y="182" font-size="10.5" fill="#92400e">  "Nasıl, ne zaman, ne kadar, neden, niçin, niye, ne (niçin)?"</text>\n  <text x="374" y="202" font-size="10.5" fill="#334155">  "Çivileri ağzına neden dolduruyorsun?"</text>\n  <text x="520" y="224" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#a16207">İsmi nitelerse SIFAT, fiili nitelerse ZARF olur!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DÜŞÜNCEYİ GELİŞTİRME YOLLARI, SÖZ SANATLARI VE İLETİŞİM</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1d4ed8">Düşünceyi Geliştirme Yolları ve Söz Sanatları</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Tanımlama ("... nedir?" sorusunun cevabı)</text>\n  <text x="40" y="118" font-size="11" fill="#334155">• Karşılaştırma (Benzerlik ve farklılıkları kıyaslama)</text>\n  <text x="40" y="138" font-size="11" fill="#334155">• Örneklendirme ve Tanık Gösterme (Alıntı yapma)</text>\n  <text x="40" y="158" font-size="11" fill="#334155">• Benzetme (Teşbih): Zayıf unsuru güçlüye benzetme</text>\n  <text x="40" y="178" font-size="11" fill="#334155">• Kişileştirme (Teşhis), Konuşturma (İntak), Abartma</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">Öyküleme ve Betimleme Anlatım Biçimleri</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">İletişim, Tartışma ve Özetleme İlkeleri</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Etkili İletişim: Göz teması, beden dili, nezaket sözleri</text>\n  <text x="375" y="120" font-size="11" fill="#334155">• Yapılandırılmış Özetleme (T.O.7.23 / T.K.7.15):</text>\n  <text x="375" y="138" font-size="10.5" fill="#334155">  Önemli bilgileri seçip kronolojik sırayla kendi</text>\n  <text x="375" y="156" font-size="10.5" fill="#334155">  cümlelerimizle kısaca ifade etmek.</text>\n  <text x="375" y="178" font-size="11" fill="#334155">• Tartışma (T.K.7.17): Görüşleri mantıklı gerekçelerle</text>\n  <text x="375" y="196" font-size="10.5" fill="#334155">  temellendirmek, tutarsız görüşleri nezaketle çürütmek.</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">Nezaket ve Empati İletişimin Anahtarıdır</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
